    private static readonly Dictionary<string, IconDefinition> Lookup = Categories
        .SelectMany(category => category.Icons)
        .ToDictionary(icon => icon.Name, StringComparer.OrdinalIgnoreCase);

    /// <summary>
    /// Resolves a Font Awesome icon name such as <c>arrow-right</c> to its definition.
    /// </summary>
    public static bool TryGet(string? name, [NotNullWhen(true)] out IconDefinition? definition)
    {
        if (string.IsNullOrWhiteSpace(name))
        {
            definition = null;
            return false;
        }

        return Lookup.TryGetValue(name.Trim(), out definition);
    }
}

/// <summary>A named group of icon definitions.</summary>
public sealed record IconCategory(string Name, IReadOnlyList<IconDefinition> Icons);
